def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The bottom row contains the five-cell pattern.
    pattern = [9, 9, 9, 3, 4]
    targets = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]

    for r, c in targets:
        start = c - len(pattern) // 2
        for i, value in enumerate(pattern):
            col = start + i
            if 0 <= col < w:
                out[r][col] = value

    return out
